pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount, address actor) public {
        // keep params in the admissible domain (wide)
        vm.assume(actor != address(0));
        vm.assume(actor != address(c));
        vm.assume(actor != address(this));
        amount = bound(amount, 1, type(uint128).max);

        // actor deposits `amount`, giving them that much credit
        vm.deal(actor, amount);
        vm.prank(actor);
        c.deposit{value: amount}();

        // actor withdraws all of their credit through the boundary entry
        vm.prank(actor);
        bool ok;
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // General rule: after a successful withdrawAll, the contract's credit
        // accounting was fully decremented, so it must hold no ether and the
        // tracked balance must equal the real ether balance.
        assertTrue(ok && address(c).balance == 0);
    }
}

