pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        vm.assume(amount > 0 && amount < type(uint256).max / 2);
        Reentrant attacker = new Reentrant();
        vm.deal(address(attacker), amount);
        attacker.deposit{value: amount}(c);
        bool ok;
        try attacker.attack(c) {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: a withdrawal (even with a re-entrant recipient) always completes without revert.
        assertTrue(ok);
    }
}

contract Reentrant {
    function deposit(C c) external payable {
        c.deposit{value: msg.value}();
    }

    function attack(C c) external {
        c.withdrawAll();
    }

    receive() external payable {
        c.withdrawAll();
    }
}

