pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1 ether, 1000 ether);
        Reentrant attacker = new Reentrant(c);
        vm.deal(address(attacker), amount);
        attacker.deposit(amount);
        bool ok;
        try attacker.attack() { ok = true; } catch { ok = false; }
        assertTrue(!ok, "re-entrant withdrawal must revert");
    }
}

contract Reentrant {
    C c;
    bool reentered;
    constructor(C _c) { c = _c; }
    function deposit(uint256 amount) external payable {
        c.deposit{value: amount}();
    }
    function attack() external {
        c.withdrawAll();
    }
    receive() external payable {
        if (!reentered) {
            reentered = true;
            c.withdrawAll();
        }
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, 1e30);
        ReentrantAttacker attacker = new ReentrantAttacker();
        attacker.setTarget(address(c));
        vm.deal(address(attacker), amount);
        vm.prank(address(attacker));
        c.deposit{value: amount}();

        bool ok;
        vm.prank(address(attacker));
        try c.withdrawAll() { ok = true; } catch { ok = false; }

        // Rule: any withdrawal (even to a re-entrant counterparty) completes
        // without reverting, and the full amount is paid out exactly once.
        assertTrue(ok && address(c).balance == 0 && address(attacker).balance == amount);
    }
}

contract ReentrantAttacker {
    C c;
    bool attempted;
    function setTarget(address t) public { c = C(t); }
    function withdrawAll() public { c.withdrawAll(); }
    receive() external payable {
        if (!attempted) {
            attempted = true;
            c.withdrawAll();
        }
    }
}
